def get_different_subcloud(subclouds, subclouds_to_exclude=None, subcloud_names_to_exclude=None):
    if subclouds_to_exclude is None:
        subclouds_to_exclude = []
    if subcloud_names_to_exclude is None:
        subcloud_names_to_exclude = []

    available_subclouds = [subcloud for subcloud in subclouds if subcloud not in subclouds_to_exclude and subcloud.get_name() not in subcloud_names_to_exclude]

    if not available_subclouds:
        raise ValueError("No different subclouds available after excluding the specified ones.")

    highest_subcloud = max(available_subclouds, key=lambda subcloud: int(subcloud.get_id()))
    return highest_subcloud
